<script setup lang="tsx">
import { computed, onMounted, onUnmounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import type { BaseTableCol, TableRowData } from "tdesign-vue-next";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { useCurrentInstance } from "@/util";
import { GetCommonErrorCode, ShowErrorTips, ShowTextTipsInfo } from "@/util/tips";
import { GetBotAgentList, ParseBotAgent, IsBotStatusRunning } from "@/apis/bot.ts";
import { GetAvatarUrl } from "@/util/avatar.ts";
import { handleGotoBotGame, handleGotoBotAgentEdit, handleGotoUsername } from "@/util/router";
import { useUserStore } from "@/stores/user.ts";
import { GetJudgeLanguageStr } from "@/apis/language";
import type { BotAgent, BotAgentView } from "@/types/bot.ts";
import type { CellParams } from "@/types/table";

const route = useRoute();
const router = useRouter();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

const userStore = useUserStore();

const dataLoading = ref(false);

const formLayout = computed(() => (isMobile.value ? "vertical" : "inline"));

// 定时器引用
let refreshTimer: number | null = null;

// 搜索表单
const searchForm = ref({
  id: 0 as number | undefined,
  name: "" as string | undefined,
  username: "" as string | undefined,
  gameKey: "" as string | undefined,
});

// 分页信息
const pagination = ref({
  current: 1,
  pageSize: 20,
  defaultCurrent: 1,
  defaultPageSize: 20,
  total: 200,
  pageSizeOptions: [20, 100],
  showPageSize: false,
});

// Agent列表数据
const agentList = ref<BotAgentView[]>([]);

// 表格列配置
const allColumns: BaseTableCol<TableRowData>[] = [
  {
    title: "ID",
    colKey: "id",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      if (data.row.inserter == userStore.getUserId) {
        return (
          <t-button variant="text" onClick={() => handleGotoBotAgentEdit(data.row.id)}>
            {data.row.id}
          </t-button>
        );
      } else {
        return <t-button variant="text">{data.row.id}</t-button>;
      }
    },
  },
  {
    title: "选手名称",
    colKey: "name",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      if (data.row.inserter == userStore.getUserId) {
        return (
          <t-button variant="text" onClick={() => handleGotoBotAgentEdit(data.row.id)}>
            {data.row.name || "无"}
          </t-button>
        );
      } else {
        return <t-button variant="text">{data.row.name || "无"}</t-button>;
      }
    },
  },
  {
    title: "游戏名称",
    colKey: "gameTitle",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return (
        <t-button variant="text" onClick={() => handleGotoBotGame(data.row.gameKey)}>
          {data.row.gameTitle}
        </t-button>
      );
    },
  },
  {
    title: "创建者",
    colKey: "inserterUsername",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const avatarUrl = GetAvatarUrl(data.row.inserterUsername, data.row.inserterEmail);
      return (
        <t-space>
          <t-avatar shape="round" size="32px" image={avatarUrl} hide-on-load-failed={false} />
          <t-button variant="text" onClick={() => handleGotoUsername(router, data.row.inserterUsername)}>
            {data.row.inserterNickname}
          </t-button>
        </t-space>
      );
    },
  },
  {
    title: "语言",
    colKey: "language",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const buttonText = GetJudgeLanguageStr(data.row.language);
      if (data.row.inserter == userStore.getUserId) {
        return (
          <t-button theme="text" onClick={() => handleGotoBotAgentEdit(data.row.id)}>
            {buttonText}
          </t-button>
        );
      } else {
        return (
          <t-button theme="text">
            {buttonText}
          </t-button>
        );
      }
    },
  },
  {
    title: "版本",
    colKey: "version",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      if (data.row.inserter == userStore.getUserId) {
        return (
          <t-button theme="text" onClick={() => handleGotoBotAgentEdit(data.row.id)}>
            {data.row.version || "无"}
          </t-button>
        );
      } else {
        return (
          <t-button theme="text">
            {data.row.version || "无"}
          </t-button>
        );
      }
    },
  },
  {
    title: "积分",
    colKey: "rank",
  },
  {
    title: "创建时间",
    colKey: "insertTime",
  },
  {
    title: "修改时间",
    colKey: "modifyTime",
  },
];

const listColumns = computed(() => {
  if (isMobile.value) {
    // 与列定义的 title 保持同一类型，便于直接比较
    const hiddenTitles: BaseTableCol<TableRowData>["title"][] = ["创建者", "语言", "版本", "积分", "修改时间"];
    return allColumns.filter((col) => !hiddenTitles.includes(col.title));
  }
  return allColumns;
});

// 搜索表单提交
const handleSearchFormSubmit = async () => {
  await router.push({
    query: {
      ...route.query,
      page: 1,
      page_size: pagination.value.pageSize,
      id: searchForm.value.id,
      name: searchForm.value.name,
      username: searchForm.value.username,
    },
  });
};

// 搜索表单重置
const handleSearchFormReset = async () => {
  searchForm.value.id = undefined;
  searchForm.value.name = "";
  searchForm.value.username = "";
  await router.push({
    query: {
      ...route.query,
      page: 1,
      page_size: pagination.value.pageSize,
      id: "",
      name: "",
      username: "",
    },
  });
};

// 新建Agent
const handleGotoCreate = async () => {
  await router.push({
    path: "/bot/agent/create",
  });
};

// 获取Agent列表
const fetchData = async (page: number, pageSize: number) => {
  dataLoading.value = true;
  try {
    const res = await GetBotAgentList(searchForm.value.id, searchForm.value.name, searchForm.value.gameKey, searchForm.value.username, page, pageSize);
    if (res.code === 0) {
      const response = res.data;
      if (Array.isArray(response)) {
        // 直接返回数组的情况
        if (response.length > 0) {
          agentList.value = response.map((item: BotAgent) => ParseBotAgent(item));
        } else {
          agentList.value = [];
          ShowTextTipsInfo(globalProperties, "未找到记录");
        }
        // 如果是数组直接返回，设置总数为数组长度
        pagination.value.total = response.length;
      } else if (response.list && response.list.length > 0) {
        // 包含list和total的情况
        agentList.value = response.list.map((item: BotAgent) => ParseBotAgent(item));
        // 更新分页总数
        if (response.total) {
          pagination.value.total = response.total;
        }
      } else {
        agentList.value = [];
        ShowTextTipsInfo(globalProperties, "未找到记录");
      }
      // 检查是否有running状态的记录，决定是否启动定时刷新
      if (hasRunningStatus()) {
        startAutoRefresh();
      } else {
        stopAutoRefresh();
      }
    } else {
      ShowErrorTips(globalProperties, res.code);
      agentList.value = [];
      stopAutoRefresh();
    }
  } catch (err) {
    console.error(err);
    ShowErrorTips(globalProperties, GetCommonErrorCode());
    agentList.value = [];
    stopAutoRefresh();
  } finally {
    dataLoading.value = false;
  }
};

// 分页变化处理
const onPageChange = async (pageInfo: { current: number; pageSize: number }) => {
  await router.push({
    query: { ...route.query, page: pageInfo.current },
  });
};

// 检查是否有running状态的记录
const hasRunningStatus = () => {
  return agentList.value.some((agent) => {
    return agent.status !== undefined && IsBotStatusRunning(agent.status);
  });
};

// 启动定时刷新
const startAutoRefresh = () => {
  if (refreshTimer !== null) {
    return;
  }
  refreshTimer = window.setInterval(() => {
    fetchData(pagination.value.current, pagination.value.pageSize);
  }, 5000);
};

// 停止定时刷新
const stopAutoRefresh = () => {
  if (refreshTimer !== null) {
    clearInterval(refreshTimer);
    refreshTimer = null;
  }
};

// 初始化
onMounted(async () => {
  watch(
    () => route.query,
    (newQuery) => {

      // 更新搜索表单
      searchForm.value = {
        id: newQuery.id ? parseInt(newQuery.id as string) : undefined,
        name: (newQuery.name as string) || undefined,
        gameKey: (newQuery.game_key as string) || undefined,
        username: (newQuery.username as string) || undefined,
      };

      const queryPage = parseInt(newQuery.page as string) || pagination.value.defaultCurrent;
      const queryPageSize = parseInt(newQuery.page_size as string) || pagination.value.defaultPageSize;

      pagination.value = { ...pagination.value, current: queryPage, pageSize: queryPageSize };
      fetchData(queryPage, queryPageSize);
    },
    { immediate: true }
  );
});

// 组件卸载时清除定时器
onUnmounted(() => {
  stopAutoRefresh();
});
</script>

<template>
  <t-card style="margin: 10px">
    <t-form :layout="formLayout" @submit="handleSearchFormSubmit" @reset="handleSearchFormReset">
      <t-form-item label="游戏标识">
        <t-input v-model="searchForm.gameKey" placeholder="请输入游戏标识" />
      </t-form-item>
      <t-form-item label="选手ID">
        <t-input v-model="searchForm.id" placeholder="请输入选手ID" type="number" />
      </t-form-item>
      <t-form-item label="选手名称">
        <t-input v-model="searchForm.name" placeholder="请输入选手名称" />
      </t-form-item>
      <t-form-item label="创建者">
        <t-input v-model="searchForm.username" placeholder="请输入创建者用户名" />
      </t-form-item>
      <t-form-item>
        <t-space>
          <t-button theme="primary" type="submit">搜索</t-button>
          <t-button theme="default" variant="base" type="reset">重置</t-button>
          <t-button theme="danger" @click="handleGotoCreate">新建</t-button>
        </t-space>
      </t-form-item>
    </t-form>

    <div style="overflow-x: auto; width: 100%">
      <t-table
:data="agentList" :columns="listColumns" row-key="id" vertical-align="top" :hover="true"
        :pagination="pagination" :loading="dataLoading" table-layout="auto" @page-change="onPageChange" />
    </div>
  </t-card>
</template>

<style scoped></style>
